source("helper.R")
d <- zujson::json_parse(paste(readLines("data/jwe.json", warn = FALSE), collapse = "\n"), simplify = "none"); t <- d$tok
ALG <- zujose_info(); KM <- ALG$algorithm[ALG$kind == "key management"]; CE <- ALG$algorithm[ALG$kind == "content encryption"]
J <- function(x) zujson::json_parse(x, simplify = "none"); W <- function(x) zujson::json_write(x)
with <- function(kj, ...) { m <- J(kj); a <- list(...); for (n in names(a)) m[[n]] <- a[[n]]; as_jwk(W(m)) }
dec <- function(label, tok, key) try_(label, jwe_decrypt(tok, key, KM, CE))
cat("--- key_ops / use on decryption keys\n")
dec("rsa key_ops [decrypt] for RSA-OAEP", t$oaep, with(d$keys$rsa, key_ops = list("decrypt")))
dec("rsa key_ops [unwrapKey]", t$oaep, with(d$keys$rsa, key_ops = list("unwrapKey")))
dec("rsa use enc", t$oaep, with(d$keys$rsa, use = "enc")); dec("rsa use sig", t$oaep, with(d$keys$rsa, use = "sig"))
dec("ec key_ops [deriveBits] for ECDH-ES", t$ecdh_p256, with(d$keys$p256, key_ops = list("deriveBits")))
dec("ec key_ops [deriveKey]", t$ecdh_p256, with(d$keys$p256, key_ops = list("deriveKey")))
dec("ec key_ops [deriveBits] ECDH-ES+A128KW", t$ecdhkw_p256, with(d$keys$p256, key_ops = list("deriveBits")))
dec("ec key_ops [unwrapKey] ECDH-ES+A128KW", t$ecdhkw_p256, with(d$keys$p256, key_ops = list("unwrapKey")))
dec("oct key_ops [decrypt] A128KW", t$kw, with(d$keys$oct16, key_ops = list("decrypt"))); dec("oct key_ops [unwrapKey] A128KW", t$kw, with(d$keys$oct16, key_ops = list("unwrapKey")))
dec("oct key_ops [unwrapKey] dir", t$dir_gcm, with(d$keys$oct32, key_ops = list("unwrapKey"))); dec("oct key_ops [decrypt] dir", t$dir_gcm, with(d$keys$oct32, key_ops = list("decrypt")))
dec("oct key_ops [decrypt] PBES2", t$pbes2, with(d$keys$pw, key_ops = list("decrypt"))); dec("oct key_ops [deriveKey] PBES2", t$pbes2, with(d$keys$pw, key_ops = list("deriveKey")))
dec("dir key alg=A256GCM", t$dir_gcm, with(d$keys$oct32, alg = "A256GCM")); dec("dir key alg=dir", t$dir_gcm, with(d$keys$oct32, alg = "dir")); dec("dir key alg=A128GCM", t$dir_gcm, with(d$keys$oct32, alg = "A128GCM"))
dec("kw key alg=A128GCM (enc)", t$kw, with(d$keys$oct16, alg = "A128GCM")); dec("rsa key alg RSA-OAEP-256 for RSA-OAEP", t$oaep, with(d$keys$rsa, alg = "RSA-OAEP-256")); dec("rsa key alg RS256", t$oaep, with(d$keys$rsa, alg = "RS256"))
cat("--- arguments\n")
for (v in list(0, 1.5, NA, -1, "1", Inf, c(1, 2), NULL, TRUE, 1L, 2^53, NaN)) try_(paste("limits token =", deparse(v)), jose_limits(token = v))
try_("jws_verify algorithms dir", jws_verify("a.b.c", jwk_oct(K32), "dir")); try_("jwe_decrypt algorithms HS256", jwe_decrypt("a.b.c.d.e", jwk_oct(K32), "HS256", "A256GCM")); try_("jwe_decrypt encryptions dir", jwe_decrypt("a.b.c.d.e", jwk_oct(K32), "dir", "dir"))
try_("algorithms character(0)", jws_verify("a.b.c", jwk_oct(K32), character())); try_("algorithms NA", jws_verify("a.b.c", jwk_oct(K32), NA_character_)); try_("algorithms list", jws_verify("a.b.c", jwk_oct(K32), list("HS256")))
try_("algorithms factor", jws_verify("a.b.c", jwk_oct(K32), factor("HS256"))); try_("algorithms w/ none among", jws_verify("a.b.c", jwk_oct(K32), c("HS256", "none")))
tok <- hs('{"alg":"HS256"}', "hello", K32); key <- jwk_oct(K32)
try_("require both", jws_verify(tok, key, "HS256", require = c("any", "all"))); try_("require bogus", jws_verify(tok, key, "HS256", require = "one")); try_("require NA", jws_verify(tok, key, "HS256", require = NA))
dt <- sub("\\.[^.]*\\.", "..", tok)
try_("payload character(0)", jws_verify(dt, key, "HS256", payload = character(0))); try_("payload NA", jws_verify(dt, key, "HS256", payload = NA_character_)); try_("payload raw", jws_verify(dt, key, "HS256", payload = charToRaw("hello"))); try_("payload list", jws_verify(dt, key, "HS256", payload = list("hello")))
try_("payload latin1", { h <- b64('{"alg":"HS256"}'); p <- "café"; s <- zucrypt::crypt_hmac(charToRaw(paste0(h, ".", b64(charToRaw(enc2utf8(p))))), K32, "sha256"); jws_verify(paste0(h, "..", b64(s)), key, "HS256", payload = iconv(p, "UTF-8", "latin1")) })
try_("as_jwk vec2", as_jwk(c("a", "b"))); try_("as_jwk_set vec2", as_jwk_set(c("a", "b"))); try_("as_jwk_set NULL", as_jwk_set(NULL)); try_("as_jwk_set jwk", as_jwk_set(key))
cat("--- b64:false JSON payload with escapes\n")
hx <- b64('{"alg":"HS256","crit":["b64"],"b64":false}')
fl <- function(pj, bytes) sprintf('{"payload":%s,"protected":"%s","signature":"%s"}', pj, hx, b64(zucrypt::crypt_hmac(c(charToRaw(paste0(hx, ".")), bytes), K32, "sha256")))
r <- try_("payload with \\u0000", jws_verify(fl('"a\\u0000b"', as.raw(c(0x61, 0, 0x62))), key, "HS256")); if (is.list(r) && !inherits(r, "error")) print(r$payload)
r <- try_("payload truncated-at-NUL forgery", jws_verify(fl('"a\\u0000b"', as.raw(0x61)), key, "HS256")); if (is.list(r) && !inherits(r, "error")) print(r$payload)
r <- try_("payload surrogate pair", jws_verify(fl('"\\ud83d\\ude00"', charToRaw(enc2utf8("\U1F600"))), key, "HS256")); if (is.list(r) && !inherits(r, "error")) print(r$payload)
r <- try_("payload empty string b64false", jws_verify(fl('""', raw()), key, "HS256")); if (is.list(r) && !inherits(r, "error")) print(r$payload)
r <- try_("b64false json + detached arg (payload absent)", jws_verify(sub('"payload":"[^"]*",', "", fl('"x"', charToRaw("x"))), key, "HS256", payload = "x"))
cat("--- peek\n")
p <- jose_peek(t$general3); str(p[setdiff(names(p), c("ciphertext", "encrypted_keys"))], max.level = 1); print(p)
p <- jose_peek(hs('{"alg":"HS256"}', '{"exp":1e400,"a":{"b":1}}', K32)); str(p$claims)
p <- jose_peek(hs('{"alg":"none"}', '{"x":1,"x":2}', K32)); print(is.null(p$claims)); print(p)
